        const locations = [
            { id: "xuanqing", name: "玄清宗", tag: "中州腹地 · 正道核心", icon: "fa-yin-yang", desc: "<p>位于中州太行灵脉之上的天下正道魁首，亦是苍玄界明面上的秩序维护者。</p><p>宗门内规矩森严，等级分明，以传统的炼气修仙为主。其护宗大阵“太清四象阵”号称能抵挡大乘期修士的全力一击。</p><p><strong>风物：</strong>随处可见的青玉广场与仙鹤，弟子皆穿素白道袍，行事板正。这里的灵气最为纯粹平和，极适合打坐修炼。</p>" },
            { id: "tianjian", name: "天剑宗", tag: "西境边界 · 断剑山脉", icon: "fa-khanda", desc: "<p>坐落于西境环境恶劣的断剑山脉，是全天下剑修的最高殿堂。</p><p>不讲究繁文缛节，只信奉“一剑破万法”。宗门内的建筑多是在悬崖峭壁上硬生生开凿出来的，主峰名为“天极峰”，峰顶常年积雪，剑气缭绕。</p><p><strong>风物：</strong>空气中总是弥漫着金属的冷厉与剑意的肃杀，宗门内最常听到的声音就是利刃出鞘与金铁交鸣。</p>" },
            { id: "taixu", name: "太虚观", tag: "九天之上 · 浮云秘境", icon: "fa-cloud-sun", desc: "<p>苍玄界最神秘的宗门，主体建筑漂浮在中州上空的云层之中，普通人终其一生也难窥其真貌。</p><p>门下弟子极少在世间走动，他们擅长推演天机、星象卜卦，自诩为“天道观察者”。</p><p><strong>风物：</strong>建筑多为虚幻的星光与云气凝结，没有重力概念，弟子常手持罗盘或龟甲，说话总是说一半留一半。</p>" },
            { id: "danxia", name: "丹霞谷", tag: "南域 · 神农鼎遗迹", icon: "fa-mortar-pestle", desc: "<p>位于南域的巨大裂谷之中，气候温暖湿润，是天下九成极品丹药的产出地。</p><p>谷内奇花异草遍地，但越美丽的地方越危险，外围的天然毒瘴让无数贪婪的散修有来无回。</p><p><strong>风物：</strong>终年被五彩斑斓的药气笼罩，随处可见巨大的炼丹炉虚影。这里的修士往往随身带着无数个装满未知药粉的瓶瓶罐罐。</p>" },
            { id: "wanqi", name: "万器山", tag: "西域 · 十万火山", icon: "fa-hammer", desc: "<p>坐落于西域的活火山群之中，利用地心熔岩之火进行法宝锻造。</p><p>这里的修士大多身材魁梧，无论男女都崇尚力量与极致的肉身防御。全大陆最顶级的法宝和防具皆出自于此。</p><p><strong>风物：</strong>炽热、烟尘、永不停歇的打铁声。山门前堆满了失败的法宝残骸，被他们戏称为“艺术的阶梯”。</p>" },
            { id: "desert", name: "赤铃沙海", tag: "南域偏西 · 百蛊绿洲", icon: "fa-bell", desc: "<p>位于南域偏西、万器山以南与十万大山以西的广阔沙海，沙风里常夹着银铃与蛊虫振翅声。</p><p>百蛊绿洲是沙海核心寨城，外来修士入寨需登记蛊契；鸣沙驿负责沙舟航线，赤沙禁域则是连老向导都要先摸护身符的高危区。</p><p><strong>风物：</strong>苗疆式银饰、彩布、蛊棚、水井账册和沙舟驼铃混在一起，热闹时像集市，严肃时像账房点名。</p>" },
            { id: "zhendao", name: "阵道阁", tag: "沧溟外海 · 阵道群岛", icon: "fa-draw-polygon", desc: "<p>孤悬于沧溟外海之上的群岛，由无数个上古连环阵法构成，整体像一座巨大的水上迷宫。</p><p>没有阵道阁的指引，外人连岛的边缘都摸不到。他们将阵法融入了生活的方方面面，甚至连吃饭的桌子都刻着保鲜阵。</p><p><strong>风物：</strong>海浪与星光交织，脚下的石板可能随时翻转把你传送到海里。这里的修士大多带着严重的黑眼圈，手里永远拿着阵图沙盘。</p>" },
            { id: "cangming", name: "沧溟海阙", tag: "沧溟内缘 · 潮汐海阙", icon: "fa-water", desc: "<p>位于星罗群岛以东、无尽海内缘以西的新兴海修势力，外界常以沧溟外海统称，真正熟悉航路的人会称其为沧溟海阙。</p><p>海阙由海修、鲛人、潮汐术士与巡潮使共同维持，掌管潮汐航路、海图许可与归墟外围封锁。外来者入阙必须领取潮印，否则会被潮汐阵送回龙绡渡。</p><p><strong>风物：</strong>半在海面半在水下的玄玉宫阙、夜间倒映星潮的潮听台、用鲛珠照明的海图司，以及随时可能改道的潮汐阵路。</p>" },
            { id: "xueyu", name: "冰原雪域", tag: "北境极寒 · 玄霜宫辖境", icon: "fa-snowflake", desc: "<p>位于苍玄界最北端，南接中州商道，北临永昼冰海，是玄霜宫镇守寒灾与白夜裂谷的边境雪域。</p><p>外来修士通常从寒渊冰市入境，购买抗寒符、租雪舟、办理雪路通行。暴雪季普通飞舟航线会失效，路引比豪言壮语可靠得多。</p><p><strong>风物：</strong>白昼漫长，风雪削灵，冰街上热汤棚与寒铁行并排营业。玄霜宫巡霜使常年巡逻，专治把勇气当棉袄的低阶修士。</p>" },
            { id: "yushou", name: "御兽宗", tag: "南疆 · 万兽山脉", icon: "fa-paw", desc: "<p>建立在南疆原始森林的边缘，门下弟子皆与妖兽签订契约，共同战斗。</p><p>相比于人类的狡诈，他们更信任灵兽的直觉。宗门内没有宏伟的大殿，多是依树而建的木屋或巨大的兽穴。</p><p><strong>风物：</strong>震天的兽吼、浓郁的野兽气息。弟子们身上多带有野兽的特征（如狼耳、蛇瞳），行事狂野不羁。</p>" },
            { id: "yaozu", name: "妖族王庭", tag: "南境深处 · 十万大山", icon: "fa-dragon", desc: "<p>被人类修士列为禁地的十万大山深处，是妖族繁衍生息的绝对领地。</p><p>这里不修金丹元婴，只修血脉与内丹。由几大上位妖族共同统治，极度排外，人类踏入通常只有成为食物或奴隶两个下场。</p><p><strong>风物：</strong>巨大到遮天蔽日的远古巨树，充满原始压迫感的图腾，以及空气中随时会让人陷入疯狂的妖气。</p>" },
            { id: "modao", name: "魔道六门", tag: "苍玄地下 · 暗河网络", icon: "fa-skull", desc: "<p>由六个松散联盟组成的魔修势力总称，藏匿于贯穿苍玄界地下的庞大暗河与溶洞网络中。</p><p>这里没有道德的束缚，只有赤裸裸的利益与力量。虽然被正道追杀，但却是黑市交易和情报流通最繁荣的地方。</p><p><strong>风物：</strong>暗红色的地下荧光苔藓、随处可见的黑市摊位、戴着面具掩藏身份的亡命之徒，以及充满诱惑与危险的修罗殿。</p>" },
            { id: "guiyu", name: "幽冥渊", tag: "西境极渊 · 鬼域底部", icon: "fa-ghost", desc: "<p>位于大陆最西端的一道深不见底的深渊，是传说中连接冥界的入口。</p><p>这里没有活人的生气，只有刺骨的阴风和游荡的残魂。少数修炼鬼道的邪修会冒险进入边缘收集阴气，但深入者从未有人生还。</p><p><strong>风物：</strong>绝对的黑暗与冰冷，耳边永远萦绕着若有若无的低泣。忘川河水在此汇聚，洗刷着一切前尘记忆。</p>" },
            { id: "tianyuan", name: "天渊城", tag: "中立交界 · 散修联盟总部", icon: "fa-city", desc: "<p>建立在正魔交界处的一座奇迹之城，受三大顶级宗门共同监督，是绝对的中立区。</p><p>城内严禁私斗，违者会遭到大阵的无情抹杀。这里是散修的天堂，只要你有灵石，可以买到任何功法、丹药甚至是某位大能的项上人头。</p><p><strong>风物：</strong>终日不歇的喧嚣，鳞次栉比的商铺与拍卖行。你可能在街边吃面的同时，看到两个化神期老怪在为一个地摊货讨价还价。</p>" },
            { id: "chengan", name: "承安皇朝", tag: "中州平原 · 太行以南", icon: "fa-vihara", desc: "<p>坐落于苍玄界最肥沃的中州平原盆地，是凡人世界最庞大、最强盛的皇朝。</p><p>与修仙宗门划江而治，井水不犯河水。这里不修仙法，但武道昌盛，皇朝的精锐铁骑配合军阵，甚至能抗衡元婴期修士。当代人皇姜澄鸢更是受天道气运加身，威压极重。</p><p><strong>风物：</strong>金碧辉煌的宫殿群、市井繁华的烟火气、严密的城防与听风楼里络绎不绝的情报客。这里没有长生不老的幻想，只有实打实的权谋与国泰民安。</p>" }
        ];

        // ================= 渲染地图与选项 =================
        const ALL_REALMS = ["炼气一层", "筑基一层", "金丹一层", "元婴一层", "化神一层", "炼虚一层", "合体一层", "大乘一层", "渡劫一层", "半步真仙", "真仙大成"];
        const $realmSelect = $('#fs-realm');
        $realmSelect.append(`<option value="自定义">-- 自定义 --</option>`);
        ALL_REALMS.forEach(r => $realmSelect.append(`<option value="${r}">${r}</option>`));
        $realmSelect.val("炼气一层");

        $realmSelect.on('change', function() {
            if ($(this).val() === '自定义') $('#fs-realm-custom').show().focus();
            else $('#fs-realm-custom').hide();
        });

        const $locSelect = $('#fs-location');
        $locSelect.append(`<option value="自定义">-- 自定义 --</option>`);

        const $mapTrack = $('#cx-map-track');
        locations.forEach((loc) => {
            $locSelect.append(`<option value="${loc.name}">${loc.name} (${loc.tag})</option>`);
            $mapTrack.append(`
                <div class="cx-loc-card" data-id="${loc.id}">
                    <div class="cx-loc-icon"><i class="fa-solid ${loc.icon}"></i></div>
                    <div class="cx-loc-info"><h3>${loc.name}</h3><span>${loc.tag}</span></div>
                </div>
            `);
        });
        $locSelect.val("玄清宗");
        $locSelect.on('change', function() {
            if ($(this).val() === '自定义') $('#fs-location-custom').show().focus();
            else $('#fs-location-custom').hide();
        });

        const pageDetail = document.getElementById('cx-detail-page');
        $('.cx-loc-card').on('click', function() {
            const id = $(this).data('id');
            const data = locations.find(l => l.id === id);
            $('#dt-icon').html(`<i class="fa-solid ${data.icon}"></i>`);
            $('#dt-name').text(data.name);
            $('#dt-tag').text(data.tag);
            $('#dt-desc').html(data.desc);
            pageDetail.classList.add('show');
        });

        // ================= 渲染与控制 3D 轮盘 =================
        const $track = $('#cx-track');
        const total = characters.length;
        const angleStep = 360 / total;
        let currentAngle = 0;
        let frontIndex = 0;
        let isAnimating = false;

        characters.forEach((char, index) => {
            const floatDelay = -(Math.random() * 4).toFixed(2);
            $track.append(`
                <div class="cx-card" data-index="${index}" data-id="${char.id}">
                    <div class="cx-card-float" style="animation-delay: ${floatDelay}s;">
                        <div class="cx-card-inner">
                            <div class="cx-card-front">
                                <img src="${char.front}" class="cx-card-img" loading="lazy">
                                <div class="cx-click-hint"><i class="fa-solid fa-eye"></i></div>
                                <div class="cx-card-overlay">
                                    <h3 class="cx-card-name">${char.name}</h3>
                                    <div class="cx-card-title">${char.title}</div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            `);
        });

        const $cards = $('.cx-card');

        window.updateCarousel = function() {
            const containerHeight = document.querySelector('.cx-3d-scene').clientHeight;
            const cardHeight = containerHeight * 0.65;
            const cardWidth = cardHeight * (2 / 3);

            // 移动端智能缩小轮盘半径，防止卡片超出屏幕
            const radiusOffset = window.innerWidth < 768 ? 70 : 150;
            const radius = Math.round((cardWidth / 2) / Math.tan(Math.PI / total)) + radiusOffset;

            $cards.each(function(index) {
                let angle = currentAngle + (index * angleStep);
                let rad = angle * (Math.PI / 180);
                let x = Math.sin(rad) * radius;
                let z = Math.cos(rad) * radius - radius;
                let normalizedAngle = angle % 360;
                if (normalizedAngle < 0) normalizedAngle += 360;
                let isFront = (normalizedAngle < 5 || normalizedAngle > 355);
                let scale = 0.6 + ((z + radius) / (radius * 2)) * 0.4;

                if (isFront) { scale = 1.1; frontIndex = index; }

                $(this).css({
                    'transform': `translate(-50%, -50%) translateX(${x}px) translateZ(${z}px) scale(${scale})`,
                    'z-index': Math.round(z + radius)
                });
                if (isFront) $(this).addClass('is-front');
                else $(this).removeClass('is-front');
            });
        };

        // ================= 角色弹窗逻辑 =================
        const charModal = document.getElementById('cx-char-modal');
        const cmFront = document.getElementById('cm-front');
        const cmAvatar = document.getElementById('cm-avatar');
        const cmName = document.getElementById('cm-name');
        const cmSect = document.getElementById('cm-sect');
        const cmTitle = document.getElementById('cm-title');
        const cmDesc = document.getElementById('cm-desc');
        const cmBtnSelect = document.getElementById('cm-btn-select');

        $cards.on('click', function(e) {
            if (isAnimating) return;
            const clickedIndex = $(this).data('index');

            if (clickedIndex === frontIndex) {
                const charData = characters[clickedIndex];
                cmFront.src = charData.front;
                cmAvatar.src = charData.avatar;
                cmName.innerText = charData.name;
                cmSect.innerText = charData.sect;
                cmTitle.innerText = charData.title;
                cmDesc.innerText = charData.desc;
                cmBtnSelect.dataset.id = charData.id;
                charModal.classList.add('show');
            } else {
                isAnimating = true;
                let diff = frontIndex - clickedIndex;
                if (diff > total / 2) diff -= total;
                if (diff < -total / 2) diff += total;
                currentAngle += diff * angleStep;
                updateCarousel();
                setTimeout(() => { isAnimating = false; }, 500);
            }
        });

        $('#btn-prev').on('click', function() { if (!isAnimating) { isAnimating = true; currentAngle += angleStep; updateCarousel(); setTimeout(() => { isAnimating = false; }, 500); }});
        $('#btn-next').on('click', function() { if (!isAnimating) { isAnimating = true; currentAngle -= angleStep; updateCarousel(); setTimeout(() => { isAnimating = false; }, 500); }});
        $('#btn-random').on('click', function() { if (!isAnimating) { isAnimating = true; let randomSteps = Math.floor(Math.random() * total) + (total * 2); currentAngle -= randomSteps * angleStep; updateCarousel(); setTimeout(() => { isAnimating = false; }, 500); }});

        window.addEventListener('resize', () => { if(document.getElementById('carousel-view').style.display === 'block') updateCarousel(); });

        // ================= 自由开局交互与写入 =================
        $('#btn-free-start').on('click', function() { $('#cx-freestart-modal').addClass('show'); });

        $('#btn-add-custom-item').on('click', function() {
            const $row = $(`<div class="cx-custom-item-row" style="display:none;"><div><input type="text" class="cx-form-input item-name" placeholder="物品名称"><input type="number" class="cx-form-input item-count" placeholder="数量" value="1" min="1" style="flex: 0 0 80px; min-width: 80px;"><button type="button" class="cx-btn-icon danger btn-remove-item"><i class="fa-solid fa-minus"></i></button></div><textarea class="cx-form-textarea item-desc" placeholder="描述一下这件物品..." style="min-height: 70px;"></textarea></div>`);
            $('#custom-items-container').append($row); $row.slideDown(300);
        });
        $(document).on('click', '.btn-remove-item', function() { $(this).closest('.cx-custom-item-row').slideUp(300, function() { $(this).remove(); }); });

        $('#btn-add-custom-npc').on('click', function() {
            const $row = $(`<div class="cx-custom-item-row" style="display:none;"><div><input type="text" class="cx-form-input npc-name" placeholder="道友姓名"><input type="text" class="cx-form-input npc-sect" placeholder="身份/宗门"><input type="text" class="cx-form-input npc-realm" placeholder="修为"><input type="text" class="cx-form-input npc-relation" placeholder="关系"><button type="button" class="cx-btn-icon danger btn-remove-npc"><i class="fa-solid fa-minus"></i></button></div><textarea class="cx-form-textarea npc-desc" placeholder="描述一下这位道友..." style="min-height: 50px;"></textarea></div>`);
            $('#custom-npcs-container').append($row); $row.slideDown(300);
        });
        $(document).on('click', '.btn-remove-npc', function() { $(this).closest('.cx-custom-item-row').slideUp(300, function() { $(this).remove(); }); });

        function showToast(text, isLoading = false) {
            const toast = document.getElementById('cx-toast');
            document.getElementById('cx-toast-text').innerText = text;
            toast.querySelector('.cx-spin-icon').style.display = isLoading ? 'inline-block' : 'none';
            toast.style.opacity = '1'; toast.style.transform = 'translateX(-50%) translateY(0)';
            if (!isLoading) setTimeout(() => { toast.style.opacity = '0'; toast.style.transform = 'translateX(-50%) translateY(-20px)'; }, 2500);
        }

        async function runStEcho(text, severity = 'info') {
            const execCmd = typeof triggerSlash === 'function' ? triggerSlash : (typeof parent.triggerSlash === 'function' ? parent.triggerSlash : null);
            const safeText = String(text).replace(/[\r\n|]/g, ' ');
            if (execCmd) {
                try {
                    await execCmd(`/echo title="苍玄界" severity=${severity} ${safeText}`);
                    return;
                } catch (err) {
                    console.error('SillyTavern echo failed', err);
                }
            }
            showToast(safeText);
        }

        async function setFirstOpeningMessage(message, swipeId = 0) {
            if (typeof setChatMessages === 'function') {
                await setChatMessages([{ message_id: 0, message, swipe_id: swipeId }], { refresh: 'affected' });
                return;
            }
            if (typeof setChatMessage === 'function') {
                await setChatMessage(message, 0, { swipe_id: swipeId, refresh: 'display_and_render_current' });
                return;
            }
            throw new Error('未连接首楼写入接口');
        }

        function getCxGlobal(name) {
            try {
                if (globalThis[name] !== undefined) return globalThis[name];
            } catch (_) {}
            try {
                if (window.parent && window.parent !== window && window.parent[name] !== undefined) return window.parent[name];
            } catch (_) {}
            return undefined;
        }

        function setCxRegexEnabled(regex, enabled) {
            if (!regex) return;
            const hasDisabled = Object.prototype.hasOwnProperty.call(regex, 'disabled');
            const hasEnabled = Object.prototype.hasOwnProperty.call(regex, 'enabled');
            if (hasDisabled) regex.disabled = !enabled;
            if (hasEnabled) regex.enabled = enabled;
            if (!hasDisabled && !hasEnabled) regex.disabled = !enabled;
        }

        async function activateFreeStartRegexAndRerender() {
            const updateRegexes = getCxGlobal('updateTavernRegexesWith');
            if (typeof updateRegexes === 'function') {
                try {
                    await updateRegexes(regexes => {
                        for (const regex of regexes) {
                            const name = regex && (regex.scriptName || regex.script_name || regex.name || '');
                            if (name === '自由开局美化') setCxRegexEnabled(regex, true);
                        }
                        return regexes;
                    }, { type: 'character', name: 'current' });
                } catch (error) {
                    console.warn('cx free-start regex activation failed', error);
                }
            }

            const emit = getCxGlobal('eventEmit');
            const events = getCxGlobal('tavern_events');
            if (typeof emit === 'function' && events && events.MESSAGE_UPDATED) {
                try {
                    await emit(events.MESSAGE_UPDATED, 0);
                } catch (error) {
                    console.warn('cx free-start message update event failed', error);
                }
            }

            if (typeof setChatMessages === 'function') {
                try {
                    await setChatMessages([{ message_id: 0 }], { refresh: 'affected' });
                    return;
                } catch (error) {
                    console.warn('cx free-start rerender failed', error);
                }
            }

            const rerender = getCxGlobal('reloadAndRenderChatWithoutEvents');
            if (typeof rerender === 'function') {
                try {
                    await rerender();
                } catch (error) {
                    console.warn('cx free-start chat refresh failed', error);
                }
            }
        }

        async function setOpeningSwipe(swipeId = 0) {
            if (typeof setChatMessages === 'function') {
                await setChatMessages([{ message_id: 0, swipe_id: swipeId }], { refresh: 'affected' });
                return;
            }
            if (typeof getChatMessages === 'function' && typeof setChatMessage === 'function') {
                const messages = await getChatMessages(0, { include_swipes: true });
                const firstMsg = messages[0];
                await setChatMessage(firstMsg.swipes[swipeId], 0, { swipe_id: swipeId, refresh: 'display_and_render_current' });
                return;
            }
            throw new Error('未连接首楼切换接口');
        }

        // --- 自由开局写入 USER档案 ---
        const WorldbookManager = {
            LOREBOOK_NAMES: ["苍玄界_修订版世界书", "我的苍玄界，才不会这么跌宕起伏！"],
            ENTRY_COMMENT: "USER档案",

            async getTargetEntry() {
                if (typeof getLorebookEntries !== 'function') {
                    throw new Error("世界书读取接口不可用：getLorebookEntries 未加载");
                }
                const tried = [];
                for (const bookName of this.LOREBOOK_NAMES) {
                    try {
                        const allEntries = await getLorebookEntries(bookName);
                        tried.push(bookName);
                        const target = Array.isArray(allEntries) ? allEntries.find(entry => entry.comment === this.ENTRY_COMMENT) : null;
                        if (target) {
                            target.__bookName = bookName;
                            return target;
                        }
                    } catch (err) {
                        tried.push(bookName + "(失败)");
                    }
                }
                throw new Error("未找到世界书 USER档案 条目，已尝试：" + tried.join("、"));
            },

            async setEntryEnabledByComment(comment, enabled) {
                if (typeof getLorebookEntries !== 'function' || typeof setLorebookEntries !== 'function') {
                    throw new Error("世界书接口不可用，无法切换条目：" + comment);
                }
                const tried = [];
                for (const bookName of this.LOREBOOK_NAMES) {
                    try {
                        const allEntries = await getLorebookEntries(bookName);
                        tried.push(bookName);
                        const target = Array.isArray(allEntries) ? allEntries.find(entry => entry.comment === comment) : null;
                        if (target) {
                            const payload = Object.assign({}, target, { enabled });
                            delete payload.__bookName;
                            await setLorebookEntries(bookName, [payload]);
                            return true;
                        }
                    } catch (err) {
                        tried.push(bookName + "(失败)");
                    }
                }
                throw new Error("未找到世界书条目：" + comment + "，已尝试：" + tried.join("、"));
            },

            async applyFabaoEntryState(fabao) {
                const shouldEnableXiaoSuo = !!fabao && fabao.id === "cat";
                await this.setEntryEnabledByComment("小索【人设】", shouldEnableXiaoSuo);
                return shouldEnableXiaoSuo;
            },

            async saveUserProfile(profileData, entryToUpdate) {
                const originalContent = entryToUpdate.content;
                const marker = "【苍玄界·" + "{{" + "user" + "}}" + "档案】";
                const markerIndex = originalContent.indexOf(marker);

                if (markerIndex === -1) {
                    throw new Error(`世界书条目格式错误，未找到锚点"${marker}"`);
                }

                const headerContent = originalContent.substring(0, markerIndex + marker.length);

                const extractOld = (regex, fallback = "无") => {
                    const match = originalContent.match(regex);
                    return match && match[1].trim() !== "" ? match[1].trim() : fallback;
                };

