  // ============================================================
  // Step 1：懒注入默认角色变量（只在不存在时插入）
  // ============================================================
  function ensureCharacterCGVariables() {
    if (typeof insertVariables !== "undefined") {
      try {
        insertVariables({ _CG相册: defaultCGState }, { type: "character" });
        console.log("[CG Manager] 角色变量初始化完成");
