        opacity: 1;
        visibility: visible;
        transform: translateY(0) scale(1);
      }
      #${FRAME_ID} {
        width: 100%;
        height: 100%;
        border: 0;
        display: block;
        background: transparent;
      }
      @media (max-width: 640px) {
        #${ROOT_ID} {
          right: 12px;
          bottom: 12px;
          width: 38px;
          height: 38px;
        }
        #${TOGGLE_ID} {
          width: 38px;
          height: 38px;
        }
        #${TOGGLE_ID} .cx-floating-status-glyph {
          font-size: 17px;
        }
        #${PANEL_ID} {
          right: 0;
          bottom: 50px;
          width: calc(100vw - 24px);
          height: min(76vh, 680px);
          border-radius: 14px;
        }
        #${ROOT_ID}.cx-open-down #${PANEL_ID} {
